"""Go2 Stair reward: flat-derived anchor plus a clearance-aware contact penalty.

Every mechanism and coefficient of the verified reference program
go2_stair_official_flat_derived_v1 is preserved unchanged; exactly one
RewardTerm is added to shape the dominant public-dev failure mode.
"""

from true_rl_agent.candidates.components import RewardTerm, TrainingComponents


def track_lin_vel_xy_exp(inputs):
    error = (
        inputs.commanded_base_vel[:, :2] - inputs.base_lin_vel[:, :2]
    ).square().sum(dim=1)
    return (-error / 0.25).exp()


def track_ang_vel_z_exp(inputs):
    error = (
        inputs.commanded_base_vel[:, 2] - inputs.base_ang_vel[:, 2]
    ).square()
    return (-error / 0.25).exp()


def ang_vel_xy_l2(inputs):
    return inputs.base_ang_vel[:, :2].square().sum(dim=1)


def flat_orientation_l2(inputs):
    return inputs.projected_gravity[:, :2].square().sum(dim=1)


def dof_torques_l2(inputs):
    return inputs.joint_torque.square().sum(dim=1)


def dof_acc_l2(inputs):
    return inputs.joint_acc.square().sum(dim=1)


def action_rate_l2(inputs):
    return inputs.action_delta.square().sum(dim=1)


def feet_air_time(inputs):
    reward = (
        (inputs.support_last_air_time - 0.5)
        * inputs.support_first_contact.float()
    ).sum(dim=1)
    moving = inputs.commanded_base_vel[:, :2].norm(dim=1) > 0.1
    return reward * moving.float()


def clearance_aware_contact_penalty(inputs):
    # Penalize contact that occurs while the base is low relative to the
    # terrain origin, which correlates with insufficient clearance and
    # riser-catching on steep shallow steps.  The penalty is bounded and
    # only active when contact is present.
    contact = inputs.support_contact.float().sum(dim=1)
    low_base = (inputs.base_height < 0.25).float()
    return contact * low_base


def build_training_components():
    return TrainingComponents(
        name="go2_stair_flat_derived_clearance_aware_contact_v1",
        reward_terms=[
            RewardTerm(name="track_lin_vel_xy_exp", weight=3.5, fn=track_lin_vel_xy_exp),
            RewardTerm(name="track_ang_vel_z_exp", weight=0.75, fn=track_ang_vel_z_exp),
            RewardTerm(name="ang_vel_xy_l2", weight=-0.05, fn=ang_vel_xy_l2),
            RewardTerm(name="flat_orientation_l2", weight=-2.5, fn=flat_orientation_l2),
            RewardTerm(name="dof_torques_l2", weight=-0.0002, fn=dof_torques_l2),
            RewardTerm(name="dof_acc_l2", weight=-2.5e-7, fn=dof_acc_l2),
            RewardTerm(name="action_rate_l2", weight=-0.01, fn=action_rate_l2),
            RewardTerm(name="feet_air_time", weight=0.25, fn=feet_air_time),
            RewardTerm(
                name="clearance_aware_contact_penalty",
                weight=-1.0,
                fn=clearance_aware_contact_penalty,
                clip_min=0.0,
                clip_max=1.0,
                description="Penalty for contact while base is low",
            ),
        ],
        rationale=(
            "Anchor: the verified reference go2_stair_official_flat_derived_v1. Its "
            "public-dev evidence is 100% success on every ID, C1-frontier, "
            "phase-composition, and C2 cell, while scalar OOD strata fail almost "
            "exclusively through forbidden_contact: 0.518 of joint_ood episodes, 0.333 "
            "of tread_ood episodes, and 0.148 of height_ood episodes, concentrated in "
            "short-tread (about 0.277-0.327 m) and tall-riser (about 0.177-0.250 m) "
            "cells. The reference program never prices forbidden contact; its only "
            "signal is the absorbing termination mask, which carries no per-step "
            "gradient. The prior candidate stair_go2_forbidden_contact_force_penalty_v1 "
            "added a dense penalty on resolved forbidden-contact force, but its runtime "
            "last_mean was 0.0 and it failed to improve the objective (0.924 vs 0.934), "
            "suggesting the force signal is too sparse or too late. Hypothesis: a "
            "bounded penalty on any support contact while the base is low (below 0.25 m) "
            "provides a smooth, dense gradient that discourages the robot from relying on "
            "low, riser-catching contact during ascent, steering the gait toward higher "
            "clearance and improving scalar OOD extrapolation. On ID cells the optimal "
            "trajectory maintains sufficient base height, so the added term is inactive "
            "there and the guard scores are protected. All other mechanisms and "
            "coefficients are copied unchanged from the anchor."
        ),
    )

from true_rl_agent.candidates.components import RewardTerm, TrainingComponents


def track_lin_vel_xy_exp(inputs):
    error = (inputs.commanded_base_vel[:, :2] - inputs.base_lin_vel[:, :2]).square().sum(dim=1)
    return (-error / 0.25).exp()


def track_ang_vel_z_exp(inputs):
    error = (inputs.commanded_base_vel[:, 2] - inputs.base_ang_vel[:, 2]).square()
    return (-error / 0.25).exp()


def ang_vel_xy_l2(inputs):
    return inputs.base_ang_vel[:, :2].square().sum(dim=1)


def flat_orientation_l2(inputs):
    return inputs.projected_gravity[:, :2].square().sum(dim=1)


def dof_torques_l2(inputs):
    return inputs.joint_torque.square().sum(dim=1)


def dof_acc_l2(inputs):
    return inputs.joint_acc.square().sum(dim=1)


def action_rate_l2(inputs):
    return inputs.action_delta.square().sum(dim=1)


def feet_air_time(inputs):
    reward = ((inputs.support_last_air_time - 0.5) * inputs.support_first_contact.float()).sum(dim=1)
    moving = inputs.commanded_base_vel[:, :2].norm(dim=1) > 0.1
    return reward * moving.float()


def ascent_clearance_descent_penalty(inputs):
    # Penalize the strike posture: base sinks below an ascent-appropriate
    # threshold while the trunk is pitched forward and the base is still
    # descending.  Unlike the rejected hard-threshold boolean, this uses a
    # smooth ReLU product so the gradient grows continuously as the robot
    # descends into the strike posture on tall-riser/short-tread OOD cells.
    clearance = 0.30 - inputs.base_height
    low = clearance.clamp(min=0.0)
    struck = inputs.projected_gravity[:, 0].clamp(min=0.0)
    descent = (-inputs.base_lin_vel[:, 2]).clamp(min=0.0)
    return low * struck * descent


def build_training_components():
    return TrainingComponents(
        name="go2_stair_strike_velocity_clearance_v3",
        reward_terms=[
            RewardTerm(name="track_lin_vel_xy_exp", weight=3.5, fn=track_lin_vel_xy_exp),
            RewardTerm(name="track_ang_vel_z_exp", weight=0.75, fn=track_ang_vel_z_exp),
            RewardTerm(name="ang_vel_xy_l2", weight=-0.05, fn=ang_vel_xy_l2),
            RewardTerm(name="flat_orientation_l2", weight=-2.5, fn=flat_orientation_l2),
            RewardTerm(name="dof_torques_l2", weight=-0.0002, fn=dof_torques_l2),
            RewardTerm(name="dof_acc_l2", weight=-2.5e-7, fn=dof_acc_l2),
            RewardTerm(name="action_rate_l2", weight=-0.01, fn=action_rate_l2),
            RewardTerm(name="feet_air_time", weight=0.25, fn=feet_air_time),
            RewardTerm(
                name="ascent_clearance_descent_penalty",
                weight=-10.0,
                fn=ascent_clearance_descent_penalty,
                clip_min=0.0,
                clip_max=1.0,
                description="Smooth penalty for low base height while pitched forward and descending",
            ),
        ],
        rationale=(
            "Closest prior candidate: go2_stair_clearance_contact_velocity_v1/v2 "
            "(rejected; 0.9403 then authoring-policy fail). Code-level difference: v2 used "
            "the boolean product contact * (base_height < 0.25), whose hard threshold sat "
            "below the base height the policy actually uses, so the term was almost never "
            "active (runtime last_mean 0.0). The current best go2_stair_clearance_aware_"
            "contact_v1 (0.9627) retains the same hard-threshold failure on F_scalar "
            "(joint_ood success 0.407, forbidden_contact 0.556). Replacement mechanism: "
            "ascent_clearance_descent_penalty is a continuously differentiable product of "
            "ReLU(0.30 - base_height), ReLU(projected_gravity_x), and ReLU(-base_lin_vel_z). "
            "It activates gradually as the base sinks below 0.30 m, bows forward, and still "
            "descends, so every policy step deeper into the strike posture receives penalty "
            "gradient before contact. It is inactive above 0.30 m, preserving the verified "
            "in-distribution protection (C0-ID and C1-ID were 1.0 in the anchor) while "
            "shaping the tall-riser/short-tread strike posture that drives the joint_ood "
            "forbidden-contact failures. All other mechanisms and coefficients are copied "
            "unchanged from the current best."
        ),
    )
